---@meta
-- A NetherForge terrain's script (terrain/<id>.lua), for lua-language-server: what the script
-- is given as `...` and what it returns. It runs apart from the server, so `nf` and the rest of nf.lua
-- aren't there.
-- Generated by packages/api/scripts/generate.ts from packages/api/src/spec. Edit the spec, then run `pnpm generate`.
-- The sandbox removes nf, io, os, debug, load, loadfile, dofile, collectgarbage, print, package, math.randomseed, string.dump.

--- The world a terrain's script shapes, and the noises its file declares: what the script is given as `...`, so it starts `local terrain = ...`. The same for every call of the script, on whichever thread.
---@class Terrain
local Terrain = {}

--- The world's seed.
---@return integer
function Terrain.seed() end

--- The y of the world's lowest block.
---@return integer
function Terrain.min_y() end

--- The y of the world's highest block.
---@return integer
function Terrain.max_y() end

--- The file's sea level: a column whose top is below it is flooded up to it.
---@return integer
function Terrain.sea_level() end

--- One of the noises the file's `script.noises` declares, by its name there: its own pattern from the world's seed, the same numbers as the file's noises. A name the file doesn't declare is an error.
---@param name string Its name in `script.noises`.
---@return Noise
function Terrain.noise(name) end

--- The y of a column's top block, as a chunk is generated with it: the file's height, then the script's `height` stage. Any column, in the chunk or not. Not from the `height` stage itself, which is given the file's. In a file with a `terrain.density`, the height the density is shaped around: the ground's blocks are the chunk's to read (`chunk:block`).
---@param x integer
---@param z integer
---@return integer
function Terrain.height(x, z) end

--- The name of the biome area a column is in (a key of the file's `biomes`), or `default` when the file has none.
---@param x integer
---@param z integer
---@return string
function Terrain.area(x, z) end

--- The biome of the area a column is in, as the file writes it: `minecraft:plains`, or a project biome's id.
---@param x integer
---@param z integer
---@return string
function Terrain.biome(x, z) end

--- A noise the file's `script.noises` declares (`terrain.noise(name)`): FastNoiseLite, as every noise of the file is, so the same numbers on the server and in the editor.
---@class Noise
local Noise = {}

--- The noise's value, from -1 to 1: with two numbers at a column (`x`, `z`), with three at a point (`x`, `y`, `z`).
---@param x number
---@param y number The column's `z` when there are two numbers.
---@param z? number The point's `z`.
---@return number
function Noise:at(x, y, z) end

--- The chunk a `terrain` or `decorate` stage is given: 16 by 16 columns of the world's whole height, which it reads and fills. Positions are the world's; a part outside the chunk is left out. Only during the stage it's given to.
---@class Chunk
local Chunk = {}

--- The chunk's x, in chunks: its blocks are `chunk:x() * 16` to `chunk:x() * 16 + 15`.
---@return integer
function Chunk:x() end

--- The chunk's z, in chunks.
---@return integer
function Chunk:z() end

--- The x of its first column: `chunk:x() * 16`.
---@return integer
function Chunk:min_x() end

--- The z of its first column: `chunk:z() * 16`.
---@return integer
function Chunk:min_z() end

--- Fills a box with a block, both corners included: the part of it in the chunk and the world. The block is an id, `minecraft:cobblestone` (the game's, written in full) or a project block's as the file names it, and one the generator places: one the file names anywhere, or that its `script.blocks` or `script.customBlocks` lists. `minecraft:air` empties the box.
---@param x1 integer One corner.
---@param y1 integer
---@param z1 integer
---@param x2 integer The other.
---@param y2 integer
---@param z2 integer
---@param block BlockId A block id.
function Chunk:fill(x1, y1, z1, x2, y2, z2, block) end

--- Sets one block, as `fill` does a box.
---@param x integer
---@param y integer
---@param z integer
---@param block BlockId A block id.
function Chunk:set(x, y, z, block) end

--- The block at a place in the chunk, as `fill` takes it (`minecraft:air` for none); `nil` outside the chunk or the world.
---@param x integer
---@param y integer
---@param z integer
---@return string?
function Chunk:block(x, y, z) end

--- What a terrain's script returns: the stages it runs, each optional. A key that isn't one of them is an error.
---@class TerrainStages
---@field height? fun(x: integer, z: integer, height: integer): number A column's height: the y of its top block, given the file's (`height`). Rounded down, and kept inside the world. Everything asks it (the terrain, the decorations, a spawn, the preview's map), so keep it quick.
---@field density? fun(x: integer, y: integer, z: integer, value: number): number Only in a file with a `terrain.density`: the density at a point (above 0 is solid), given the file's (`value`, in blocks: the ground's height above or below the point, moved by its 3D noises, or the islands'). Asked at the points of a grid 4 blocks apart across and 8 up (`x` and `z` multiples of 4, `y` of 8), and blended between them for the blocks, so keep it smooth: what it changes is blended too. Every point of the world's height is asked, so a file with one draws its map more slowly.
---@field terrain? fun(chunk: Chunk) After the file's terrain (its stone, layers and sea), before caves, the floor and ores: fills the chunk.
---@field decorate? fun(chunk: Chunk) After the file's decorations, last: places blocks in the chunk.
